        } else if (!ranges::all_of(w, [&T](char c) { return ranges::contains(T, c); })) { // 青木語の単語である可能性がないなら
            cout << "Takahashi" << endl; // 高橋語の単語
        } else { //どちらの可能性もあるなら
            cout << "Unknown" << endl; // 確定しない
        }
    }

    return 0;
}

